// Idk how necessary this is, but I adapted their
// movement and tile management code for this project, and I want to make sure
// They get the credit they deserve for it.
package com.gielinorexplored.utils;

import com.gielinorexplored.ExploredTile;
import java.util.*;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;

@Singleton
public class GielinorExploredTileUtils {
  private static final String CONFIG_GROUP = "gielinorExplored";
  private static final String DATA_PREFIX = "region_data";
  @Getter private final List<WorldPoint> exploredTiles = new ArrayList<>();
  private final Client client;
  private final ConfigManager configManager;

  @Inject
  GielinorExploredTileUtils(Client client, ConfigManager configManager) {
    this.client = client;
    this.configManager = configManager;
  }

  private Collection<WorldPoint> translateToWorldPoint(Collection<ExploredTile> points) {
    if (points.isEmpty()) {
      return Collections.EMPTY_LIST;
    }

    return points.stream()
        .map(
            point ->
                WorldPoint.fromRegion(
                    point.getRegionId(), point.getRegionX(), point.getRegionY(), point.getPlane()))
        .flatMap(
            worldPoint -> {
              final Collection<WorldPoint> localWorldPoints =
                  WorldPoint.toLocalInstance(client, worldPoint);
              return localWorldPoints.stream();
            })
        .collect(Collectors.toList());
  }

  private Collection<ExploredTile> decodeTiles(int regionId, int plane) {
    List<ExploredTile> exploredTileList = new ArrayList<>();
    String key = getKey(regionId, plane);
    String encoded = configManager.getConfiguration(CONFIG_GROUP, key);

    if (encoded == null) {
      return exploredTileList;
    }

    byte[] bytes = Base64.getUrlDecoder().decode(encoded);
    if (bytes == null || bytes.length == 0) {
      return exploredTileList;
    }

    BitSet bitSet = BitSet.valueOf(bytes);

    for (int i = bitSet.nextSetBit(0); i >= 0; i = bitSet.nextSetBit(i + 1)) {
      int tileRegionY = i / 64;
      int tileRegionX = i - (64 * tileRegionY);
      exploredTileList.add(new ExploredTile(regionId, tileRegionX, tileRegionY, plane));
    }

    return exploredTileList;
  }

  private String getKey(int regionId, int plane) {
    return DATA_PREFIX + "_" + regionId + "_" + plane;
  }

  public Collection<ExploredTile> getTiles(int regionId, int plane) {
    return decodeTiles(regionId, plane);
  }

  public void clearExploredTiles() {
    exploredTiles.clear();
  }

  public void updateExploredTiles() {
    exploredTiles.clear();

    int[] regions = client.getTopLevelWorldView().getMapRegions();
    if (regions == null) {
      return;
    }

    for (int regionId : regions) {
      Collection<WorldPoint> worldPoint =
          translateToWorldPoint(getTiles(regionId, client.getTopLevelWorldView().getPlane()));
      exploredTiles.addAll(worldPoint);
    }
  }

  public void updateTileMark(LocalPoint localPoint) {
    int plane = client.getTopLevelWorldView().getPlane();
    WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, localPoint);
    int regionId = worldPoint.getRegionID();
    ExploredTile exploredTile =
        new ExploredTile(regionId, worldPoint.getRegionX(), worldPoint.getRegionY(), plane);
    Collection<ExploredTile> regionTiles = getTiles(regionId, plane);

    if (!regionTiles.contains(exploredTile)) {
      regionTiles.add(exploredTile);
      exploredTiles.add(worldPoint);
      addTiles(regionTiles, regionId, plane);
    }
  }

  private void addTiles(Collection<ExploredTile> tiles, int regionId, int plane) {
    String key = getKey(regionId, plane);
    encodeTiles(tiles, key);
  }

  private void encodeTiles(Collection<ExploredTile> tiles, String key) {
    if (tiles == null || tiles.isEmpty()) {
      configManager.unsetConfiguration(CONFIG_GROUP, key);
      return;
    }

    BitSet output = new BitSet(4096);
    for (ExploredTile tile : tiles) {
      output.set(tile.getRegionY() * 64 + tile.getRegionX());
    }

    configManager.setConfiguration(CONFIG_GROUP, key, output.toByteArray());
  }
}

package com.gielinorexplored;

import lombok.Value;

@Value
public class ExploredTile {
  private int regionId;
  private int regionX;
  private int regionY;
  private int plane;
}

package com.gielinorexplored;

import java.awt.*;
import net.runelite.client.config.*;

/** Plugin Config. */
@ConfigGroup("gielinorExplored")
public interface GielinorExploredConfig extends Config {

  /** Turn Fog on or off */
  @ConfigItem(keyName = "fogshow", name = "Show Fog", description = "Show Fog")
  default boolean enableFog() {
    return true;
  }

  /** Toggles to show Fog on map */
  @ConfigItem(
      keyName = "mapshow",
      name = "Show Fog on World Map",
      description = "Show Fog on World Map")
  default boolean showOnWorldMap() {
    return true;
  }

  /** Toggles to show Fog on minimap */
  @ConfigItem(
      keyName = "minimapshow",
      name = "Show Fog on Mini Map",
      description = "Show Fog on Mini Map")
  default boolean showOnMiniMap() {
    return true;
  }

  /** Option for Fog Color */
  @Alpha
  @ConfigItem(
      keyName = "fogColor",
      name = "Fog Color",
      description = "Change the color of the fog.")
  default Color fogColor() {
    return new Color(0, 0, 0, 200);
  }
}

package com.gielinorexplored.overlays;

import com.gielinorexplored.ExploredTile;
import com.gielinorexplored.GielinorExploredConfig;
import com.gielinorexplored.utils.GielinorExploredTileUtils;
import java.awt.*;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class GielinorExploredWorldMapOverlay extends Overlay {
  private static final int REGION_SIZE = 1 << 6;
  private static final int REGION_TRUNCATE = ~((1 << 6) - 1);
  private final Client client;
  private final GielinorExploredConfig config;
  private final GielinorExploredTileUtils tileUtils;
  private int fogImageHeight = -1;
  private int fogImageWidth = -1;
  private BufferedImage fogBufferedImage;
  private Graphics2D fogGraphics;

  @Inject
  private GielinorExploredWorldMapOverlay(
          Client client, GielinorExploredConfig config, GielinorExploredTileUtils tileUtils) {
    this.client = client;
    this.config = config;
    this.tileUtils = tileUtils;
    setPosition(OverlayPosition.DYNAMIC);
    setPriority(Overlay.PRIORITY_HIGH);
    setLayer(OverlayLayer.ABOVE_WIDGETS);
  }

  @Override
  public Dimension render(Graphics2D graphics) {
    if (!config.showOnWorldMap()) {
      return null;
    }

    drawOnWorldMap(graphics);
    return null;
  }

  private void drawOnWorldMap(Graphics2D graphics) {
    Widget worldMap = client.getWidget(ComponentID.WORLD_MAP_MAPVIEW);
    if (worldMap == null) {
      return;
    }

    Float pixelsPerTile = client.getWorldMap().getWorldMapZoom();
    Rectangle worldMapRectangle = worldMap.getBounds();
    Graphics2D fogGraphic = getFogGraphic(worldMapRectangle);

    // Apply Fog
    fogGraphic.setComposite(AlphaComposite.Src);
    fogGraphic.setColor(getFogColor());
    fogGraphic.fillRect(0, 0, worldMapRectangle.width, worldMapRectangle.height);

    int tileWidth = (int) Math.ceil(worldMapRectangle.getWidth() / pixelsPerTile);
    int tileHeight = (int) Math.ceil(worldMapRectangle.getHeight() / pixelsPerTile);
    Point worldMapPosition = client.getWorldMap().getWorldMapPosition();

    int yTileMin = worldMapPosition.getY() - tileHeight / 2;
    int xRegionMin = (worldMapPosition.getX() - tileWidth / 2) & REGION_TRUNCATE;
    int xRegionMax = ((worldMapPosition.getX() + tileWidth / 2) & REGION_TRUNCATE) + REGION_SIZE;
    int yRegionMin = (yTileMin & REGION_TRUNCATE);
    int yRegionMax = ((worldMapPosition.getY() + tileHeight / 2) & REGION_TRUNCATE) + REGION_SIZE;
    int regionPixelSize = (int) Math.ceil(REGION_SIZE * pixelsPerTile);

    // Clear Fog.
    fogGraphic.setComposite(AlphaComposite.Clear);

    for (int x = xRegionMin; x < xRegionMax; x += REGION_SIZE) {
      for (int y = yRegionMin; y < yRegionMax; y += REGION_SIZE) {
        int regionId = ((x >> 6) << 8) | (y >> 6);
        int plane = client.getTopLevelWorldView().getPlane();

        for (final ExploredTile tile : tileUtils.getTiles(regionId, plane)) {
          if (tile.getPlane() != plane) {
            continue;
          }
          int yTileOffset = -(yTileMin - y) + 2;
          int xTileOffset = x + tileWidth / 2 - worldMapPosition.getX();

          int xPos = ((int) (xTileOffset * pixelsPerTile));
          int yPos = (worldMapRectangle.height - (int) (yTileOffset * pixelsPerTile));

          int size = (regionPixelSize / (64 - Math.round(48f * ((8f - pixelsPerTile) / 7f))));
          int tileSize = regionPixelSize / 64;

          fogGraphic.fillRect(
              xPos + (tile.getRegionX() * tileSize),
              yPos - (tile.getRegionY() * tileSize) + tileSize,
              size - 1,
              size - 1);
        }
      }
    }
    graphics.drawImage(fogBufferedImage, worldMapRectangle.x, worldMapRectangle.y, null);
  }

  private Graphics2D getFogGraphic(Rectangle bounds) {
    int w = bounds.width;
    int h = bounds.height;
    if (fogBufferedImage == null || fogImageWidth != w || fogImageHeight != h) {
      if (fogGraphics != null) {
        fogGraphics.dispose();
      }
      fogBufferedImage = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
      fogGraphics = fogBufferedImage.createGraphics();
      fogImageWidth = w;
      fogImageHeight = h;
    }
    return fogGraphics;
  }

  private Color getFogColor() {
    return config.fogColor();
  }
}

package com.gielinorexplored.overlays;

import static net.runelite.api.widgets.ComponentID.MINIMAP_CONTAINER;

import com.gielinorexplored.GielinorExploredConfig;
import com.gielinorexplored.GielinorExploredPlugin;
