import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class GielinorExploredMiniMapOverlay extends Overlay {
  private static final int MAX_DRAW_DISTANCE = 16;
  private static final int TILE_WIDTH = 4;
  private static final int TILE_HEIGHT = 4;

  private final Client client;
  private final GielinorExploredPlugin plugin;
  private final GielinorExploredTileUtils tileUtils;
  private final GielinorExploredConfig config;
  private int fogImageWidth = -1;
  private int fogImageHeight = -1;
  private BufferedImage fogBufferedImage;
  private Graphics2D fogGraphics;

  @Inject
  private GielinorExploredMiniMapOverlay(
          Client client, GielinorExploredConfig config, GielinorExploredPlugin plugin, GielinorExploredTileUtils tileUtils) {
    this.client = client;
    this.plugin = plugin;
    this.config = config;
    this.tileUtils = tileUtils;
    setPosition(OverlayPosition.DYNAMIC);
    setPriority(Overlay.PRIORITY_LOW);
    setLayer(OverlayLayer.ABOVE_WIDGETS);
  }

  @Override
  public Dimension render(Graphics2D graphics) {
    if (!config.showOnMiniMap()) {
      return null;
    }

    if (client.getLocalPlayer() == null) {
      return null;
    }

    if (plugin.lastPlane != client.getTopLevelWorldView().getPlane()) {
      tileUtils.updateExploredTiles();
      plugin.updateLastPlane();
    }

    Widget minimap = client.getWidget(MINIMAP_CONTAINER);
    if (minimap == null || minimap.isHidden()) {
      return null;
    }

    Rectangle bounds = minimap.getBounds();
    Graphics2D fogGraphic = getFogGraphic(bounds);

    // Apply Fog
    fogGraphic.setComposite(AlphaComposite.Src);
    fogGraphic.setColor(getFogColor());
    fogGraphic.fillRect(0, 0, bounds.width, bounds.height);

    // Remove walked areas.
    fogGraphic.setComposite(AlphaComposite.Clear);
    WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();
    for (WorldPoint worldPoint : tileUtils.getExploredTiles()) {
      if (worldPoint.getPlane() != playerLocation.getPlane()) {
        continue;
      }
      if (worldPoint.distanceTo(playerLocation) >= MAX_DRAW_DISTANCE) {
        continue;
      }
      LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
      if (localPoint == null) {
        continue;
      }
      Point posOnMinimap = Perspective.localToMinimap(client, localPoint);
      if (posOnMinimap == null) {
        continue;
      }
      fogGraphic.fillRect(
          posOnMinimap.getX() - bounds.x - TILE_WIDTH / 2,
          posOnMinimap.getY() - bounds.y - TILE_HEIGHT / 2,
          TILE_WIDTH,
          TILE_HEIGHT);
    }

    Shape prevClip = graphics.getClip();
    graphics.setClip(minimapCircle(bounds));
    graphics.drawImage(fogBufferedImage, bounds.x, bounds.y, null);
    graphics.setClip(prevClip);
    return null;
  }

  private Graphics2D getFogGraphic(Rectangle bounds) {
    int w = bounds.width;
    int h = bounds.height;
    if (fogBufferedImage == null || fogImageWidth != w || fogImageHeight != h) {
      if (fogGraphics != null) {
        fogGraphics.dispose();
      }
      fogBufferedImage = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
      fogGraphics = fogBufferedImage.createGraphics();
      fogImageWidth = w;
      fogImageHeight = h;
    }
    return fogGraphics;
  }

  private Ellipse2D minimapCircle(Rectangle bounds) {
    return new Ellipse2D.Double(
        bounds.x + 50, bounds.y + -2, bounds.width * .76, bounds.height * .79);
  }

  private Color getFogColor() {
    return config.fogColor();
  }
}

package com.gielinorexplored.overlays;

import com.gielinorexplored.GielinorExploredConfig;
import com.gielinorexplored.GielinorExploredPlugin;
import com.gielinorexplored.utils.GielinorExploredTileUtils;
import java.awt.*;
import java.util.Collection;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class GielinorExploredOverlay extends Overlay {
  private static final int MAX_DRAW_DISTANCE = 32;
  private final Client client;
  private final GielinorExploredPlugin plugin;
  private final GielinorExploredConfig config;
  private final GielinorExploredTileUtils tileUtils;

  @Inject
  private GielinorExploredOverlay(
          Client client, GielinorExploredConfig config, GielinorExploredPlugin plugin, GielinorExploredTileUtils tileUtils) {
    this.client = client;
    this.plugin = plugin;
    this.config = config;
    this.tileUtils = tileUtils;
    setPosition(OverlayPosition.DYNAMIC);
    setPriority(Overlay.PRIORITY_LOW);
    setLayer(OverlayLayer.ABOVE_SCENE);
  }

  @Override
  public Dimension render(Graphics2D graphics) {
    if (!config.enableFog()) {
      return null;
    }

    if (client.getLocalPlayer() == null) {
      return null;
    }

    if (plugin.lastPlane != client.getTopLevelWorldView().getPlane()) {
      tileUtils.updateExploredTiles();
      plugin.updateLastPlane();
    }

    int viewportX = client.getViewportXOffset();
    int viewportY = client.getViewportYOffset();
    int viewportW = client.getViewportWidth();
    int viewportH = client.getViewportHeight();

    Shape prevClip = graphics.getClip();
    Composite prevComposite = graphics.getComposite();

    graphics.clipRect(viewportX, viewportY, viewportW, viewportH);

    /* Apply Fog */
    graphics.setComposite(AlphaComposite.SrcOver);
    graphics.setColor(getFogColor());
    graphics.fillRect(viewportX, viewportY, viewportW, viewportH);

    /* Clear Fog from Visited Points. */
    graphics.setComposite(AlphaComposite.Clear);

    final Collection<WorldPoint> visitedPoints = tileUtils.getExploredTiles();
    WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();
    Tile[][][] tiles = client.getTopLevelWorldView().getScene().getTiles();
    int plane = plugin.lastPlane;

    for (int x = 0; x < tiles[plane].length; x++) {
      for (int y = 0; y < tiles[plane][x].length; y++) {
        Tile tile = tiles[plane][x][y];
        if (tile == null) {
          continue;
        }

        WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, tile.getLocalLocation());
        if (worldPoint.getPlane() != plane) {
          continue;
        }

        if (!visitedPoints.contains(worldPoint)) {
          continue;
        }

        if (worldPoint.distanceTo(playerLocation) >= MAX_DRAW_DISTANCE) {
          continue;
        }

        Polygon polygon = Perspective.getCanvasTilePoly(client, tile.getLocalLocation());
        if (polygon != null) {
          graphics.fill(polygon);
        }
      }
    }

    unHidePlayer(graphics, client.getLocalPlayer());
    graphics.setComposite(prevComposite);
    graphics.setClip(prevClip);
    return null;
  }

  private void unHidePlayer(Graphics2D graphics, Player player) {
    if (player == null) {
      return;
    }

    Shape playerShape = player.getConvexHull();
    if (playerShape != null) {
      graphics.fill(playerShape);
      return;
    }

    Polygon tilePolygon = player.getCanvasTilePoly();
    if (tilePolygon!= null) {
      graphics.fill(tilePolygon);
    }
  }

  private Color getFogColor() {
    return config.fogColor();
  }
}

package com.gielinorexplored;

import com.gielinorexplored.overlays.*;
import com.gielinorexplored.utils.*;
import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(name = "Gielinor Explored")
public class GielinorExploredPlugin extends Plugin {
  public int lastPlane;
  @Inject private GielinorExploredTileUtils tileUtils;
  @Inject private GielinorExploredMovementUtils movementUtils;
  @Inject private GielinorExploredOverlay gielinorExploredOverlay;
  @Inject private GielinorExploredMiniMapOverlay gielinorExploredMiniMapOverlay;
  @Inject private GielinorExploredWorldMapOverlay gielinorExploredWorldMapOverlay;
  @Inject private Client client;
  @Inject private OverlayManager overlayManager;

  @Override
  protected void startUp() throws Exception {
    log.debug("Gielinor Explored Starting up.");
    overlayManager.add(gielinorExploredOverlay);
    overlayManager.add(gielinorExploredMiniMapOverlay);
    overlayManager.add(gielinorExploredWorldMapOverlay);
    updateLastPlane();
    tileUtils.updateExploredTiles();
  }

  @Override
  protected void shutDown() throws Exception {
    overlayManager.remove(gielinorExploredOverlay);
    overlayManager.remove(gielinorExploredMiniMapOverlay);
    overlayManager.remove(gielinorExploredWorldMapOverlay);
    tileUtils.clearExploredTiles();
    log.debug("Gielinor Explored Shutting Down.");
  }

  @Provides
  GielinorExploredConfig provideConfig(ConfigManager configManager) {
    return configManager.getConfig(GielinorExploredConfig.class);
  }

  @Subscribe
  public void onGameTick(GameTick tick) {
    movementUtils.addCurrentTile();
  }

  @Subscribe
  public void onGameStateChanged(GameStateChanged gameStateChanged) {
    if (gameStateChanged.getGameState() != GameState.LOGGED_IN) {
      movementUtils.setLastTile(null);
    }

    tileUtils.updateExploredTiles();
    updateLastPlane();
  }

  public void updateLastPlane() {
    lastPlane = client.getTopLevelWorldView().getPlane();
    movementUtils.setLastPlane(lastPlane);
  }
}
